    #include <iostream>
#include <vector>
using namespace std;

void insert(vector<int>& heap, int value)
{
    // Add the new element to the end of the heap
    heap.push_back(value);

    // Get the index of the last element
    int index = heap.size() - 1;

    // Compare the new element with its parent and swap if necessary
    while (index > 0
           && heap[(index - 1) / 2] < heap[index]) {
        swap(heap[index], heap[(index - 1) / 2]);

        // Move up the tree to the parent of the current element
        index = (index - 1) / 2;
    }
}

// Function to move an element up the heap
void heapifyUp(vector<int>& heap, int index)
{
    while (index > 0
           && heap[(index - 1) / 2] < heap[index]) {
        swap(heap[index], heap[(index - 1) / 2]);
        index = (index - 1) / 2;
    }
}

// Function to move an element down the heap
void heapifyDown(vector<int>& heap, int index)
{
    while (true) {
        int left_child = 2 * index + 1;
        int right_child = 2 * index + 2;
        int largest = index;

        if (left_child < heap.size() && heap[left_child] > heap[largest]) {
            largest = left_child;
        }
        if (right_child < heap.size() && heap[right_child] > heap[largest]) {
            largest = right_child;
        }
        if (largest != index) {
            swap(heap[index], heap[largest]);
            index = largest;
        } else {
            break;
        }
    }
}

// Function to delete a node from the max-heap
void deleteMax(vector<int>& heap, int value)
{
    // Find the index of the element to be deleted
    int index = -1;
    for (int i = 0; i < heap.size(); i++) {
        if (heap[i] == value) {
            index = i;
            break;
        }
    }

    // If the element is not found, return
    if (index == -1) {
        return;
    }

    // Replace the element to be deleted with the last element
    heap[index] = heap[heap.size() - 1];

    // Remove the last element
    heap.pop_back();

    // If the deleted element was the last element
    if (index >= heap.size()) {
        return;
    }

    // Heapify the tree starting from the element at the deleted index
    if (index > 0 && heap[index] > heap[(index - 1) / 2]) {
        heapifyUp(heap, index);
    } else {
        heapifyDown(heap, index);
    }
}

int main()
{
    vector<int> arr;
    vector<int> values = {13, 16, 31, 41, 51, 100};
    int n = values.size();

    for (int i = 0; i < n; i++) {
        insert(arr, values[i]);
    }

    cout << "Initial heap: ";
    for (int j = 0; j < arr.size(); j++) {
        cout << arr[j] << " ";
